svg.script:
const NS = 'http://www.w3.org/2000/svg';
// ticks around the rim
const ticks = document.getElementById('ticks');
for (let i = 0; i < 72; i++) {
  const a = i * Math.PI / 36, long = i % 6 === 0;
  const r1 = long ? 330 : 340, r2 = 362;
  const l = document.createElementNS(NS, 'line');
  l.setAttribute('x1', 512 + Math.sin(a) * r1); l.setAttribute('y1', 640 - Math.cos(a) * r1);
  l.setAttribute('x2', 512 + Math.sin(a) * r2); l.setAttribute('y2', 640 - Math.cos(a) * r2);
  ticks.appendChild(l);
}
// leaves along both vines (positions picked by hand along the curves)
const leafSpots = [
  [112,945,-150],[88,860,-120],[72,780,-100],[100,700,-70],[130,630,-130],[118,540,-95],[110,455,-60],[140,385,-110],[190,320,-70],[240,262,-45],
  [905,950,-30],[950,860,-60],[968,775,-80],[925,690,-110],[890,640,-50],[905,555,-85],[918,460,-120],[880,400,-70],[835,335,-100],[795,290,-130],
];
const leaves = document.getElementById('leaves'), leafInk = document.getElementById('leafInk');
leafSpots.forEach(([x, y, rot], i) => {
  const s = 0.8 + (i % 3) * 0.18;
  const d = `M0,0 C18,-22 52,-24 78,0 C52,24 18,22 0,0 Z`;
  const mk = (parent, attrs) => { const p = document.createElementNS(NS, 'path'); p.setAttribute('d', d);
    p.setAttribute('transform', `translate(${x} ${y}) rotate(${rot}) scale(${s})`);
    for (const k in attrs) p.setAttribute(k, attrs[k]); parent.appendChild(p); };
  mk(leaves, { fill: i % 2 ? '#8DB584' : '#6FA06A', opacity: .92 });
  mk(leafInk, {});
  const vein = document.createElementNS(NS, 'path'); vein.setAttribute('d', 'M4,0 C28,-3 50,-2 70,0');
  vein.setAttribute('transform', `translate(${x} ${y}) rotate(${rot}) scale(${s})`); vein.setAttribute('stroke-width', 2);
  leafInk.appendChild(vein);
});
